#!/usr/bin/env node
// Odyssey: parallel worktrees, each with its own ports, .env, containers and tunnels.
// Generated by the dev-setup `odyssey` skill. Only the CONFIG block is project-specific.
import { spawn, spawnSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { createInterface } from "node:readline";
import { parseArgs } from "node:util";

const CONFIG = {
  // The branch new branches are cut from (`new <branch>` without --from)
  baseBranch: "main",
  // The main checkout is slot 0, each worktree takes the first free slot:
  // a service's port = portStart + slot * portStep + offset
  portStart: 3000,
  portStep: 100,
  // Services started by `dev` and `up`. {port} is the service's own port
  services: [{ name: "web", offset: 0, command: "npm run dev -- --port {port}" }],
  env: {
    // Copied from the main checkout into the worktree, with `vars` rewritten
    source: ".env",
    target: ".env",
    // Placeholders: {name}, {slot}, {project}, {port:<service>}
    vars: {},
    // Other gitignored files copied as they are
    copy: [],
  },
  // Commands run in a new worktree (install, library builds, ...)
  setup: ["npm ci"],
  // true: a COMPOSE_PROJECT_NAME per worktree, so containers and volumes do not collide
  compose: false,
  // Port-forwards to remote services, reopened when they drop
  outbound: [
    // { name: "api-staging", port: 3002, command: "kubectl --context staging port-forward -n app svc/api 3002:80" },
  ],
  // Branches that carry code to production: a warning on every start. null turns it off
  productionBranch: /^(main$|hotfix\/)/,
};

const RETRY_MS = 3000;

const USAGE = `Usage:
  odyssey new <branch> [--from <base>]   create the worktree with its own ports and .env
  odyssey dev [name]                     start the worktree's services (default: the current one)
  odyssey up [name...]                   outbound tunnels + every worktree's services, in one terminal
  odyssey list                           worktrees, slots, ports and state
  odyssey rm <name>                      stop the containers and remove the worktree (the branch stays)
  odyssey tunnels                        the outbound port-forwards only
  odyssey expose [name] [--service s]    expose a service on the Internet through cloudflared
  odyssey hook-create | hook-remove      for Claude Code's WorktreeCreate / WorktreeRemove hooks`;

// stdout stays free: in a Claude Code hook it must carry the worktree path only
const log = (...args) => console.error(...args);

const git = (args, cwd = process.cwd()) => {
  const result = spawnSync("git", args, { cwd, encoding: "utf8" });
  if (result.status !== 0) throw new Error(`git ${args.join(" ")}: ${result.stderr.trim()}`);
  return result.stdout.trim();
};

const run = (command, cwd, env = {}) => {
  const result = spawnSync(command, {
    cwd,
    shell: true,
    stdio: ["ignore", 2, 2],
    env: { ...process.env, ...env },
  });
  if (result.status !== 0) throw new Error(`'${command}' failed in ${cwd}`);
};

const commonDir = () => resolve(git(["rev-parse", "--path-format=absolute", "--git-common-dir"]));
const mainRoot = () => dirname(commonDir());

// Outside the repository: IDEs do not index twice, and each worktree opens as its own project
const worktreesRoot = () => join(dirname(mainRoot()), `${basename(mainRoot())}.wt`);

// Slots live under the git common dir, beside dev-setup's other state: never tracked, shared by every worktree
const stateFile = () => join(commonDir(), "dev-setup", "odyssey", "slots.json");
const readState = () => (existsSync(stateFile()) ? JSON.parse(readFileSync(stateFile(), "utf8")) : {});
const writeState = (state) => {
  mkdirSync(dirname(stateFile()), { recursive: true });
  writeFileSync(stateFile(), `${JSON.stringify(state, null, 2)}\n`);
};

const projectName = (name) =>
  `${basename(mainRoot())}-${name}`.toLowerCase().replace(/[^a-z0-9_-]/g, "-");

const portsFor = (slot) =>
  Object.fromEntries(
    CONFIG.services.map((service) => [
      service.name,
      CONFIG.portStart + slot * CONFIG.portStep + service.offset,
    ]),
  );

const render = (template, context) =>
  template
    .replace(/\{port:([\w-]+)\}/g, (_, service) => context.ports[service])
    .replace(/\{(name|slot|project|port)\}/g, (_, key) => context[key]);

const listWorktrees = () => {
  const main = mainRoot();
  const state = readState();
  return git(["worktree", "list", "--porcelain"], main)
    .split("\n\n")
    .map((block) => {
      const path = block.match(/^worktree (.+)$/m)?.[1];
      const branch = block.match(/^branch refs\/heads\/(.+)$/m)?.[1] ?? "(detached)";
      // No slot: a worktree odyssey did not create (e.g. Claude Code's default ones)
      const slot = path === main ? 0 : state[path];
      return { path, name: basename(path), branch, slot };
    });
};

const composeEnv = (worktree) =>
  CONFIG.compose ? { COMPOSE_PROJECT_NAME: projectName(worktree.name) } : {};

const isListening = (port) =>
  spawnSync("lsof", ["-nP", `-iTCP:${port}`, "-sTCP:LISTEN"]).status === 0;

const branchExists = (branch) =>
  ["refs/heads/", "refs/remotes/origin/"].some(
    (prefix) =>
      spawnSync("git", ["show-ref", "--verify", "--quiet", `${prefix}${branch}`], {
        cwd: mainRoot(),
      }).status === 0,
  );

const nextFreeSlot = () => {
  const used = new Set(Object.values(readState()));
  let slot = 1;
  while (used.has(slot)) slot += 1;
  return slot;
};

const setEnvVar = (content, key, value) => {
  const pattern = new RegExp(`^${key}=.*$`, "m");
  return pattern.test(content)
    ? content.replace(pattern, `${key}=${value}`)
    : `${content.trimEnd()}\n${key}=${value}\n`;
};

const writeEnv = (worktree) => {
  const main = mainRoot();
  const source = join(main, CONFIG.env.source);
  const context = {
    name: worktree.name,
    slot: worktree.slot,
    project: projectName(worktree.name),
    ports: portsFor(worktree.slot),
  };
  let content = existsSync(source) ? readFileSync(source, "utf8") : "";
  for (const [key, value] of Object.entries(CONFIG.env.vars)) {
    content = setEnvVar(content, key, render(value, context));
  }
  if (CONFIG.compose) content = setEnvVar(content, "COMPOSE_PROJECT_NAME", context.project);
  writeFileSync(join(worktree.path, CONFIG.env.target), content);
  for (const file of CONFIG.env.copy) {
    if (existsSync(join(main, file))) copyFileSync(join(main, file), join(worktree.path, file));
  }
};

// `from` is a remote branch (the new command) or a local commit (the Claude Code hook)
const createWorktree = (branch, { from = `origin/${CONFIG.baseBranch}`, path } = {}) => {
  const main = mainRoot();
  const target = path ?? join(worktreesRoot(), branch.replaceAll("/", "-"));
  if (existsSync(target)) throw new Error(`already exists: ${target}`);

  if (from.startsWith("origin/")) git(["fetch", "origin"], main);
  if (branchExists(branch)) {
    git(["worktree", "add", target, branch], main);
  } else {
    // --no-track: the new branch must not take its base as upstream
    git(["worktree", "add", "--no-track", "-b", branch, target, from], main);
  }

  const worktree = { path: target, name: basename(target), branch, slot: nextFreeSlot() };
  writeState({ ...readState(), [target]: worktree.slot });
  writeEnv(worktree);
  for (const command of CONFIG.setup) run(command, target, composeEnv(worktree));

  const ports = Object.entries(portsFor(worktree.slot))
    .map(([service, port]) => `${service} :${port}`)
    .join(", ");
  log(`\n✔ ${branch}\n  folder: ${target}\n  slot:   ${worktree.slot} (${ports})`);
  if (CONFIG.productionBranch?.test(branch)) log("  ⚠️  PRODUCTION branch");
  return target;
};

const findWorktree = (name) => {
  const cwd = process.cwd();
  const match = name
    ? listWorktrees().find((worktree) => worktree.name === name || worktree.branch === name)
    : listWorktrees()
        .filter((worktree) => cwd === worktree.path || cwd.startsWith(`${worktree.path}/`))
        .sort((a, b) => b.path.length - a.path.length)[0];
  if (!match) throw new Error(`worktree not found: ${name ?? cwd}`);
  if (match.slot === undefined) throw new Error(`${match.name} has no slot: odyssey did not create it`);
  return match;
};

const children = new Set();
let stopping = false;

// Each process gets its own process group (detached): stopping it stops its children too
const stopAll = () => {
  stopping = true;
  for (const child of children) {
    try {
      process.kill(-child.pid, "SIGTERM");
    } catch {
      // already gone
    }
  }
  process.exit(0);
};

const stopOnSignal = () => {
  process.on("SIGINT", stopAll);
  process.on("SIGTERM", stopAll);
};

// Every process writes to the same terminal: each line carries its process's label
const spawnLabelled = (label, command, cwd, env = {}) => {
  const child = spawn(command, {
    cwd,
    shell: true,
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
    env: { ...process.env, FORCE_COLOR: "1", ...env },
  });
  children.add(child);
  for (const stream of [child.stdout, child.stderr]) {
    createInterface({ input: stream }).on("line", (line) => console.log(`[${label}] ${line}`));
  }
  child.on("exit", (code) => {
    children.delete(child);
    if (!stopping) log(`[${label}] exited (code ${code})`);
  });
  return child;
};

const startServices = (worktree) => {
  if (CONFIG.productionBranch?.test(worktree.branch)) {
    log(`⚠️  ${worktree.name}: PRODUCTION branch`);
  }
  const ports = portsFor(worktree.slot);
  for (const service of CONFIG.services) {
    const label = `${worktree.name}/${service.name} :${ports[service.name]}`;
    if (isListening(ports[service.name])) {
      log(`[${label}] already listening, skipped`);
      continue;
    }
    spawnLabelled(
      label,
      render(service.command, {
        ...worktree,
        project: projectName(worktree.name),
        ports,
        port: ports[service.name],
      }),
      worktree.path,
      composeEnv(worktree),
    );
  }
};

// Port-forwards drop on every timeout or expired token: reopen them while this process lives
const forward = (tunnel) => {
  const child = spawnLabelled(`tunnel ${tunnel.name}`, tunnel.command, mainRoot());
  child.on("exit", () => {
    if (stopping) return;
    log(`[tunnel ${tunnel.name}] reconnecting in ${RETRY_MS / 1000}s`);
    setTimeout(() => forward(tunnel), RETRY_MS);
  });
};

const startTunnels = () => {
  for (const tunnel of CONFIG.outbound) {
    if (isListening(tunnel.port)) log(`[tunnel ${tunnel.name}] :${tunnel.port} already listening, skipped`);
    else forward(tunnel);
  }
};

// A cloudflared quick tunnel: the URL changes on every start, so it does not suit registered callbacks
const expose = (name, serviceName = CONFIG.services[0].name) => {
  const worktree = findWorktree(name);
  const port = portsFor(worktree.slot)[serviceName];
  if (port === undefined) throw new Error(`unknown service: ${serviceName}`);
  spawnLabelled(`expose ${worktree.name}/${serviceName}`, `cloudflared tunnel --url http://localhost:${port}`, worktree.path);
};

const printList = () => {
  const rows = [["name", "branch", "slot", "services"]];
  for (const worktree of listWorktrees()) {
    const services =
      worktree.slot === undefined
        ? "-"
        : Object.entries(portsFor(worktree.slot))
            .map(([service, port]) => `${service}:${port}${isListening(port) ? " ●" : ""}`)
            .join("  ");
    rows.push([worktree.name, worktree.branch, String(worktree.slot ?? "-"), services]);
  }
  for (const tunnel of CONFIG.outbound) {
    rows.push([`tunnel ${tunnel.name}`, "-", "-", `:${tunnel.port}${isListening(tunnel.port) ? " ●" : ""}`]);
  }
  const widths = rows[0].map((_, column) => Math.max(...rows.map((row) => row[column].length)));
  for (const row of rows) console.log(row.map((cell, column) => cell.padEnd(widths[column])).join("  "));
  console.log("\n● = listening");
};

const removeWorktree = (path) => {
  const main = mainRoot();
  if (path === main) throw new Error("the main checkout is not removed");
  const worktree = listWorktrees().find((item) => item.path === path);
  if (CONFIG.compose && worktree) run("docker compose down", path, composeEnv(worktree));
  // No --force: git refuses when there are uncommitted changes
  git(["worktree", "remove", path], main);
  const state = readState();
  delete state[path];
  writeState(state);
  log(`✔ removed ${path}${worktree ? ` (the branch ${worktree.branch} stays)` : ""}`);
};

const readHookInput = () => JSON.parse(readFileSync(0, "utf8"));

const { positionals, values } = parseArgs({
  allowPositionals: true,
  options: { from: { type: "string" }, service: { type: "string" } },
});
const [command, name] = positionals;

try {
  if (command === "new") {
    if (!name) throw new Error("a branch name is required");
    createWorktree(name, values.from ? { from: `origin/${values.from}` } : {});
  } else if (command === "dev") {
    stopOnSignal();
    startServices(findWorktree(name));
  } else if (command === "up") {
    stopOnSignal();
    const names = positionals.slice(1);
    startTunnels();
    for (const worktree of listWorktrees()) {
      if (worktree.slot === undefined) continue;
      if (names.length && !names.includes(worktree.name) && !names.includes(worktree.branch)) continue;
      startServices(worktree);
    }
  } else if (command === "list") {
    printList();
  } else if (command === "rm") {
    if (!name) throw new Error("a worktree name is required");
    removeWorktree(findWorktree(name).path);
  } else if (command === "tunnels") {
    stopOnSignal();
    startTunnels();
  } else if (command === "expose") {
    stopOnSignal();
    expose(name, values.service);
  } else if (command === "hook-create") {
    // Replaces Claude Code's own worktree creation, which then skips .worktreeinclude:
    // the files to carry over belong in CONFIG.env.copy
    const input = readHookInput();
    const from = git(["rev-parse", "HEAD"], input.cwd);
    const path = createWorktree(`worktree-${input.name}`, {
      from,
      path: join(worktreesRoot(), `claude-${input.name}`),
    });
    console.log(path);
  } else if (command === "hook-remove") {
    removeWorktree(readHookInput().worktree_path);
  } else {
    console.log(USAGE);
    process.exitCode = command ? 1 : 0;
  }
} catch (error) {
  log(`✖ ${error.message}`);
  process.exitCode = 1;
}
